import{_ as e,a as o}from"./chunks/ruankao_2025-11-01_110148_889.1wswICOv.js";import{_ as t,o as l,c as r,at as i}from"./chunks/framework.CY22Hent.js";const k=JSON.parse('{"title":"系统分析师笔记04_计算机网络与分布式系统","description":"","frontmatter":{"title":"系统分析师笔记04_计算机网络与分布式系统","date":"2026-08-21T00:00:00.000Z","lastUpdated":"2026-08-21T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/系统分析师笔记04_计算机网络与分布式系统.md","filePath":"blogs/软考/系统分析师笔记04_计算机网络与分布式系统.md"}'),p={name:"blogs/软考/系统分析师笔记04_计算机网络与分布式系统.md"};function h(n,a,d,c,s,u){return l(),r("div",null,[...a[0]||(a[0]=[i('<p>[toc]</p><h1 id="系统分析师笔记04-计算机网络与分布式系统" tabindex="-1">系统分析师笔记04_计算机网络与分布式系统 <a class="header-anchor" href="#系统分析师笔记04-计算机网络与分布式系统" aria-label="Permalink to &quot;系统分析师笔记04_计算机网络与分布式系统&quot;">​</a></h1><p>该笔记内容来自《系统分析师教程》第2版。</p><h2 id="计算机网络基础" tabindex="-1">计算机网络基础 <a class="header-anchor" href="#计算机网络基础" aria-label="Permalink to &quot;计算机网络基础&quot;">​</a></h2><h3 id="数据通信基础" tabindex="-1">数据通信基础 <a class="header-anchor" href="#数据通信基础" aria-label="Permalink to &quot;数据通信基础&quot;">​</a></h3><p>通信中产生和发送信息的一端称为信源，接收信息的一端称为信宿，信源和信宿之间的通信线路称为信道。信息在进入信道时要变换为适合信道传输的形式。</p><p>信道的物理性质不同，对通信的速率和传输质量的影响也不同。</p><p>另外，信息在传输过程中可能会受到外界的干扰(常称为噪声)，不同的物理信道受各种干扰的影响不同，例如，如果信道上传输的是电信号，就会受到外界电磁场的干扰，光纤信道则基本不受电磁场干扰。</p><h3 id="数据编码" tabindex="-1">数据编码 <a class="header-anchor" href="#数据编码" aria-label="Permalink to &quot;数据编码&quot;">​</a></h3><p>在计算机中，数据是以离散的二进制比特流方式表示的，称为数字数据。</p><p>在网络中传输时，通信信道有模拟信道和数字信道两种类型。</p><ul><li>计算机数据在模拟信道中传输时，要将数字信号转换成模拟信道能够识别的模拟信号。</li><li>计算机数据在数字信道中传输时，要把计算机中的数字信号转换成网络媒体能够识别且利于网络传输的数字信号。</li></ul><h3 id="差错控制" tabindex="-1">差错控制 <a class="header-anchor" href="#差错控制" aria-label="Permalink to &quot;差错控制&quot;">​</a></h3><p>通信过程中出现的差错可大致分为两类:一类是由热噪声引起的随机错误;另一类是由冲击噪声引起的突发错误。</p><p>通信线路中的热噪声是由电子的热运动产生的，热噪声时刻存在，具有很宽的频谱，且幅度较小。通信线路的信噪比越高，热噪声引起的差错越少。这种差错具有随机性，影响个别位。</p><p>冲击噪声源是外界的电磁干扰，例如，打雷闪电时产生的电磁干扰，电焊机引起的电压波动等。冲击噪声持续的时间短而幅度大，往往引起一个位串出错，属于突发性差错。</p><p>突发性差错影响局部，而随机性差错总是断续存在，影响全局。因此要尽量提高通信设备的信噪比，以满足要求的差错率。此外，要进一步提高传输质量，就需要采用有效的差错控制办法。</p><h4 id="奇偶校验检错码" tabindex="-1">奇偶校验检错码 <a class="header-anchor" href="#奇偶校验检错码" aria-label="Permalink to &quot;奇偶校验检错码&quot;">​</a></h4><p>奇偶校验是最常用的检错方法，其原理是在7位的ASCII代码后增加一位，使码字中1的个数成奇数(奇校验)或偶数(偶校验)。</p><p>经过传输后，如果其中一位(甚至奇数个位)出错，则接收端按同样的规则就能发现错误。这种方法简单实用，但只能对付少量的随机性错误。</p><h4 id="海明码" tabindex="-1">海明码 <a class="header-anchor" href="#海明码" aria-label="Permalink to &quot;海明码&quot;">​</a></h4><p>1950年，海明(Hamming)研究了用冗余数据位来检测和纠正代码差错的理论和方法。</p><p>按照海明的理论，可以在数据代码上添加若干冗余位组成码字。码字之间的海明距离是一个码字要变成另一个码字时必须改变的最小位数。</p><p>例如，7位ASCII码增加一位奇偶位成为8位的码字，这128个8位的码字之间的海明距离是2。所以，当其中一位出错时便能检测出来。两位出错时就变成另外一个码字了。</p><h4 id="循环冗余校验码" tabindex="-1">循环冗余校验码 <a class="header-anchor" href="#循环冗余校验码" aria-label="Permalink to &quot;循环冗余校验码&quot;">​</a></h4><p>暂无</p><h2 id="网络体系结构与协议" tabindex="-1">网络体系结构与协议 <a class="header-anchor" href="#网络体系结构与协议" aria-label="Permalink to &quot;网络体系结构与协议&quot;">​</a></h2><p>网络体系结构是指计算机网络的各层及其协议的集合。计算机之间要交换数据，就必须遵守一些事先约定好的规则，用于规定信息的格式以及如何发送和接收信息的一套规则就称为网络协议。</p><p>通常，网络协议由如下3个要素组成:</p><ul><li>语法，即控制信息或数据的结构和格式。</li><li>语义，即需要发出何种控制信息、完成何种动作以及做出何种应答。</li><li>同步，即事件实现顺序的详细说明。</li></ul><h3 id="osi网络结构" tabindex="-1">OSI网络结构 <a class="header-anchor" href="#osi网络结构" aria-label="Permalink to &quot;OSI网络结构&quot;">​</a></h3><p>计算机网络是相当复杂的系统，相互通信的两个计算机系统必须高度协调才能正常工作。为了设计这样复杂的计算机网络，人们提出了将网络分层的方法。分层可将庞大而复杂的问题转化为若干较小的局部问题进行处理，从而使问题简单化。</p><p>国际标准化组织(ISO)在 1977年成立了一个分委员会专门研究网络通信的体系结构问题，并提出了开放系统互连参考模型(Open System Interconnection Reference Model, OSI/RM)，它是一个定义异种计算机连接标准的框架结构。OSI为连接分布式应用处理的“开放”系统提供了基础。所谓“开放”，是指任何两个系统只要遵守参考模型和有关标准就能够进行互连。</p><p>OSI采用了层次化结构的构造技术。ISO的任务是定义一组层次和每一层所完成的功能和服务。层次的划分应当从逻辑上将功能分组，层次应该足够多，应使每一层小到易于管理的程度，但也不能太多，否则汇集各层的处理开销太大。</p><h4 id="iso-osi-参考模型" tabindex="-1">ISO/OSI 参考模型 <a class="header-anchor" href="#iso-osi-参考模型" aria-label="Permalink to &quot;ISO/OSI 参考模型&quot;">​</a></h4><p>ISO/OSI 的参考模型一共有七层，如图所示。由低层至高层分别为物理层、数据链路层、网络层、传输层、会话层、表示层和应用层。</p><p><img src="'+e+'" alt="ruankao_2025-11-01_111209_648.png" loading="lazy"></p><blockquote><p>物理层</p></blockquote><p>物理层提供为建立、维护和拆除物理链路所需的机械、电气、功能和规程的特性;提供有关在传输介质上传输非结构的位流及物理链路故障检测指示。</p><p>物理层的任务就是为物理介质提供一个物理连接。例如规定使用电缆和接头的类型，传送信号的电压等。</p><p>在这一层，数据还没有被组织，仅作为原始的位流或电气电压处理，单位是位。</p><blockquote><p>数据链路层</p></blockquote><p>数据链路层负责在两个相邻结点间的线路上无差错地传送以帧为单位的数据,并进行流量控制。每一帧包括一定数量的数据和一些必要的控制信息。</p><p>和物理层相似，数据链路层要负责建立、维持和释放数据链路的连接。在传送数据时，如果接收点检测到所传数据中有差错，就要通知发送方重发这一帧。</p><p>在这一层，信息的传送单位是帧。</p><blockquote><p>网络层(Network Layer)</p></blockquote><p>网络层为传输层实体提供端到端的交换网络数据功能，使得传输层摆脱路由选择、交换方式和拥挤控制等网络传输细节;可以为传输层实体建立、维持和拆除一条或多条通信路径;对网络传输中发生的不可恢复的差错予以报告。</p><p>在计算机网络中进行通信的两个计算机之间可能会经过很多个数据链路，也可能还要经过很多通信子网。网络层的任务就是选择合适的网间路由和交换结点，确保数据及时传送。网络层将数据链路层提供的帧组成数据包，包中封装有网络层包头，其中含有逻辑地址信息，即源站点和目的站点的网络地址。</p><p>在这一层，信息的传送单位是帧组成的数据包。</p><blockquote><p>传输层(TranspontLayer)</p></blockquote><p>传输层为会话层实体提供透明、可靠的数据传输服务，保证端到端的数据完整性;选择网络层能提供最适宜的服务;提供建立、维护和拆除传输连接功能。</p><p>传输层根据通信子网的特性最佳地利用网络资源，为两个端系统(也就是源站和目的站)的会话层之间提供建立、维护和取消传输连接的功能，并以可靠和经济的方式传输数据。</p><p>在这一层，信息的传送单位是报文。</p><blockquote><p>会话层(SessionLayer)</p></blockquote><p>会话层为彼此合作的表示层实体提供建立、维护和结束会话连接的功能;完成通信进程的逻辑名字与物理名字间的对应;提供会话管理服务。这一层也可以称为会话层或对话层，在会话层及以上的高层中，数据传送的单位不再另外命名，统称为报文。</p><p>会话层不参与具体的传输，它提供包括访问验证和会话管理在内的建立和维护应用之间通信的机制。例如服务器验证用户登录便是由会话层完成的。</p><blockquote><p>表示层(PresentationLayer)</p></blockquote><p>表示层为应用层进程提供能解释所交换信息含义的一组服务，即将要交换的数据从适合于某一用户的抽象语法转换为适合于 OSI系统内部使用的传送语法:提供格式化的表示和转换数据服务。</p><p>数据的压缩、解压缩、加密和解密等工作都由表示层负责。</p><blockquote><p>应用层(ApplicationLayer)</p></blockquote><p>应用层为OSI用户提供服务，即确定进程之间通信的性质,以满足用户需要以及提供网络与用户应用软件之间的接口服务。例如事务处理程序、电子邮件和网络管理程序等。</p><p>简而言之 ISO/OSI 七层模型（从下到上）：</p><ol><li>物理层：二进制数据传输，物理链路和物理特性相关</li><li>数据链路层：将数据封装成帧进行传送，准确传送至局域网内的物理主机上</li><li>网络层：数据分组传输和路由选择，能准确的将数据传送至互联网的网络主机上</li><li>传输层：端到端的连接，传送数据至主机端口上</li><li>会话层：管理主机之间的会话，提供会话管理服务（建立、维护和结束会话）</li><li>表示层：提供解释所交换信息含义的服务，包括数据之间的格式转换、压缩、加密等操作，对数据进行处理</li><li>应用层：实现具体的应用功能。直接进程间的通信</li></ol><h3 id="tcp-ip-协议簇" tabindex="-1">TCP/IP 协议簇 <a class="header-anchor" href="#tcp-ip-协议簇" aria-label="Permalink to &quot;TCP/IP 协议簇&quot;">​</a></h3><p>暂无</p><h3 id="网络地址" tabindex="-1">网络地址 <a class="header-anchor" href="#网络地址" aria-label="Permalink to &quot;网络地址&quot;">​</a></h3><p>Internet 依靠TCP/IP协议簇在全球范围内实现不同硬件结构、不同操作系统、不同网络系统的互连。在Internet上，每个节点都依靠唯一的IP地址互相区分和相互联系。</p><h4 id="ip地址" tabindex="-1">IP地址 <a class="header-anchor" href="#ip地址" aria-label="Permalink to &quot;IP地址&quot;">​</a></h4><p>暂无</p><h4 id="子网" tabindex="-1">子网 <a class="header-anchor" href="#子网" aria-label="Permalink to &quot;子网&quot;">​</a></h4><h4 id="超网" tabindex="-1">超网 <a class="header-anchor" href="#超网" aria-label="Permalink to &quot;超网&quot;">​</a></h4><h4 id="ipv6" tabindex="-1">IPV6 <a class="header-anchor" href="#ipv6" aria-label="Permalink to &quot;IPV6&quot;">​</a></h4><h2 id="局域网与广域网" tabindex="-1">局域网与广域网 <a class="header-anchor" href="#局域网与广域网" aria-label="Permalink to &quot;局域网与广域网&quot;">​</a></h2><p>局域网(Local Area Network，LAN)是将分散在有限地理范围内的多台计算机通过传输媒体连接起来的通信网络，通过功能完善的网络软件，实现计算机之间的相互通信和资源共享;</p><p>广域网(Wide Area Network，WAN)是在传输距离较长的前提下所发展的相关技术的集合，用于将大区域范围内的各种计算机设备和通信设备互连在一起，组成一个资源共享的通信网络。</p><h3 id="局域网" tabindex="-1">局域网 <a class="header-anchor" href="#局域网" aria-label="Permalink to &quot;局域网&quot;">​</a></h3><p>构成局域网的网络拓扑结构主要有星形结构、总线结构、环形结构和网状结构。</p><h4 id="网络的拓扑结构" tabindex="-1">网络的拓扑结构 <a class="header-anchor" href="#网络的拓扑结构" aria-label="Permalink to &quot;网络的拓扑结构&quot;">​</a></h4><p>网络拓扑结构是指网络中通信线路和结点的几何排序，用于表示整个网络的结构外貌，反映各结点之间的结构关系。它影响着整个网络的设计、功能、可靠性和通信费用等重要方面,是计算机网络十分重要的要素。</p><p>常见的网络拓扑结构包括总线型结构、星型结构、环型结构、树型结构、分布式结构，如图所示。</p><p><img src="'+o+'" alt="ruankao_2025-11-01_110148_889.png" loading="lazy"></p><blockquote><p>总线型结构（线路利用率低、干扰大、但是价格低）</p></blockquote><p>总线型拓扑结构如图10-2(a)所示，其特点为只有一条双向通路，便于进行广播式传送信息;</p><p>总线型拓扑结构属于分布式控制，无须中央处理器，故结构比较简单;结点的增、删和位置的变动较容易，变动中不影响网络的正常运行，系统扩充性能好;结点的接口通常采用无源线路，系统可靠性高;设备少、价格低、安装使用方便。</p><p>但是由于电气信号通路多，干扰较大，因此对信号的质量要求高;负载重时，线路的利用率较低;网上的信息延迟时间不确定，故障隔离和检测闲难。</p><blockquote><p>星型结构(交换机形成的局域网、中央单元负荷大）</p></blockquote><p>在星型结构中，使用中央交换单元以放射状连接到网中的各个结点，如图10-2(b)所示。中央单元采用电路交换方式以建立所希望通信的两结点间专用的路径。通常用双绞线将结点与中央单元进行连接。</p><p>其特点为维护管理容易，重新配置灵活:故障隔离和检测容易;网络延迟时间短;各结点与中央交换单元直接连通，各结点之间通信必须经过中央单元转换;网络共享能力差;线路利用率低，中央单元负荷重。</p><blockquote><p>环型结构（流动方向固定、效率低,扩充难）</p></blockquote><p>环型结构的信息传输线路构成一个封闭的环型，各结点通过中继器连入网内，各中继器间首尾相接，信息单向沿环路逐点传送，如图10-2(c)所示。</p><p>其特点为信息的流动方向是固定的，两个结点仅有一条通路，路径控制简单;有旁路设备，结点一旦发生故障，系统自动旁路，可靠性高;信息要串行穿过多个结点，在网中结点过多时传输效率低，系统响应速度慢;由于环路封闭，扩充较难。</p><blockquote><p>树型结构（总线型的扩充、分级结构）</p></blockquote><p>树型结构是总线型结构的扩充形式，传输介质是不封闭的分支电缆，如图10-2(d)所示。它主要用于多个网络组成的分级结构中，其特点同总线型网。</p><blockquote><p>分布式结构（任意节点连接、管理难、成本高)</p></blockquote><p>分布式结构无严格的布点规定和形状，各结点之间有多条线路相连，如图10-2(e)所示。其特点为有较高的可靠性，当一条线路有故障时，不会影响整个系统工作;资源共享方便，网络响应时问短;由于结点与多个结点连接，故结点的路由选择和流量控制难度大，管理软件复杂;硬件成本高。</p><h3 id="以太网" tabindex="-1">以太网 <a class="header-anchor" href="#以太网" aria-label="Permalink to &quot;以太网&quot;">​</a></h3><p>暂无</p><h3 id="无线局域网" tabindex="-1">无线局域网 <a class="header-anchor" href="#无线局域网" aria-label="Permalink to &quot;无线局域网&quot;">​</a></h3><h3 id="广域网" tabindex="-1">广域网 <a class="header-anchor" href="#广域网" aria-label="Permalink to &quot;广域网&quot;">​</a></h3><h2 id="网络工程" tabindex="-1">网络工程 <a class="header-anchor" href="#网络工程" aria-label="Permalink to &quot;网络工程&quot;">​</a></h2><p>网络工程的建设是一个极其复杂的系统工程，是对计算机网络、信息系统建设和项目管理等领域知识的综合利用的过程，系统分析师必须根据用户单位的需求和具体情况，结合当前网络技术的发展和产品化程度，经过充分的需求分析和市场调研，确定网络建设方案，依据方案有计划、分步骤地实施。</p><p>按照实施过程的先后，网络工程可分为网络规划、网络设计和网络实施3个阶段。</p><h3 id="网络规划" tabindex="-1">网络规划 <a class="header-anchor" href="#网络规划" aria-label="Permalink to &quot;网络规划&quot;">​</a></h3><p>网络规划是网络建设过程中非常重要的环节，同时也是一个系统性的过程。网络规划包括网络需求分析、可行性研究和对现有网络的分析与描述。</p><h3 id="网络设计" tabindex="-1">网络设计 <a class="header-anchor" href="#网络设计" aria-label="Permalink to &quot;网络设计&quot;">​</a></h3><p>网络设计的工作是在网络规划的基础上，设计一个能够解决用户问题的方案。在整个设计过程中，首先要确定网络总体目标和设计原则，然后设计网络的逻辑结构，再设计网络的物理结构。</p><h3 id="网络实施" tabindex="-1">网络实施 <a class="header-anchor" href="#网络实施" aria-label="Permalink to &quot;网络实施&quot;">​</a></h3><p>网络实施是在网络设计的基础上进行设备的购买、安装、调试和系统切换工作。</p><h2 id="分布式系统" tabindex="-1">分布式系统 <a class="header-anchor" href="#分布式系统" aria-label="Permalink to &quot;分布式系统&quot;">​</a></h2><h2 id="构建与中间件" tabindex="-1">构建与中间件 <a class="header-anchor" href="#构建与中间件" aria-label="Permalink to &quot;构建与中间件&quot;">​</a></h2><h2 id="web服务" tabindex="-1">web服务 <a class="header-anchor" href="#web服务" aria-label="Permalink to &quot;web服务&quot;">​</a></h2><h2 id="云计算" tabindex="-1">云计算 <a class="header-anchor" href="#云计算" aria-label="Permalink to &quot;云计算&quot;">​</a></h2>',112)])])}const _=t(p,[["render",h]]);export{k as __pageData,_ as default};
